create table if not exists spiritual.tasbih_sessions ( id bigint generated always as identity primary key, preset_id bigint references spiritual.tasbih_presets (id), custom_phrase text, target_count integer not null default 33, completed_count integer not null default 0, started_at timestamptz default now(), completed_at timestamptz, duration_seconds integer, category text default 'general', user_id uuid not null references identity.profiles (id) default auth.uid(), tenant_id uuid references core.tenants (id), created_at timestamptz default now() );
